def G(t):
    R=[("ChatGPT","Чат Джі-Пі-Ті"),("Gemini Notebook","Джеміні Ноутбук"),("NotebookLM","Ноутбук Ел-Ем"),("Gemini","Джеміні"),("Google Classroom","Гугл Класрум"),
       ("Classroom","Класрум"),("Google Forms","Гугл Формс"),("Google","Гугл"),("Claude","Клод"),("Deep Research","Діп Рісьорч"),("Study mode","Стаді мод"),
       ("Nano Banana","Нано Банана"),("Excel","Ексель"),("Дія.AI","Дія Ей-Ай"),("SMM","Ес-Ем-Ем"),("Workspace for Education","Воркспейс фор Едʼюкейшн"),("Skills","скіли"),
       ("YouTube","Ютуб"),("Canva","Канва"),("PDF","Пі-Ді-Еф"),("ДПС","податкова")]
    for a,b in R: t=t.replace(a,b)
    t=re.sub(r"ШІ-(\w+)", r"\1 штучного інтелекту", t)
    for a,b in [("від ШІ","від штучного інтелекту"),("з ШІ","зі штучним інтелектом"),("ШІ не","штучний інтелект не")]: t=t.replace(a,b)
    return t.replace("ШІ","штучний інтелект")

